export * from '@primeuix/utils';

/**
 * Applies the theme's `classPrefix` to a class value: a string, an array or an object of classes.
 *
 * @param value The class value.
 * @param prefix The `classPrefix`. Without one, or with `p`, `value` is returned as is.
 * @returns The class list with `p-` classes renamed.
 */
export declare function prefixClasses<T>(value: T, prefix?: string): T | string;

/**
 * Applies the theme's `classPrefix` to the `.p-` classes in a selector or a piece of CSS.
 *
 * @param selector The selector or CSS.
 * @param prefix The `classPrefix`. Without one, or with `p`, `selector` is returned as is.
 * @returns The selector with `.p-` classes renamed.
 */
export declare function prefixSelector<T extends string | null | undefined>(selector: T, prefix?: string): T;

/**
 * Reads `classPrefix` from a theme's options.
 *
 * @param theme The theme to read, usually `Theme` or an isolated theme.
 * @returns The prefix, or `undefined` when the installed `@primeuix/styled` cannot rename classes.
 */
export declare function getClassPrefix(theme: { getOptions?(): any; styleName?(name: string): string } | null | undefined): string | undefined;

/**
 * Returns the app's own theme in isolated mode, otherwise the shared `Theme`.
 *
 * @param isolation The app's isolation, if it has one.
 * @returns The theme the app styles itself with.
 */
export declare function getActiveTheme(isolation?: { theme?: any } | null): any;

/**
 * Returns the event bus of the theme `getActiveTheme` picks.
 *
 * @param isolation The app's isolation, if it has one.
 * @returns The bus that emits `theme:change` for that theme.
 */
export declare function getThemeService(isolation?: { theme?: any } | null): any;

/**
 * Returns the `classPrefix` of an app's theme. The value is cached per app and follows theme changes.
 *
 * @param app The `$primevue` object of the app.
 * @returns The prefix, or `undefined` when the app has no theme.
 */
export declare function getAppClassPrefix(app: any): string | undefined;

